#!/usr/bin/env python3
"""Build the two static teaching pages from the original diagnostic data.

Requires Node and KaTeX (as does render-textbook-maths.cjs). Set NODE_PATH to
an installed KaTeX node_modules directory if it is not installed locally.
The PDF/Overleaf files are built by build-algebra-diagnostic-pdfs.py.
"""
from pathlib import Path
from html import escape as e
import json, re, subprocess, os
from site_navigation import install_archive_navigation

ROOT=Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'data/algebra-diagnostic.json').read_text())
ORIGIN='https://maths.arijasad.com/'
TEMPLATE=(ROOT/'algebra-and-factorisation.html').read_text()
HEADER=re.search(r'  <header class="site-header">.*?</header>',TEMPLATE,re.S)[0].replace(' aria-current="page"','')
FOOTER=re.search(r'  <footer>.*?</footer>',TEMPLATE,re.S)[0]
CALCULUS={
 'prompt':r'Let \(f(x)=x^3-3x\) on \([-\sqrt3,\sqrt3]\). Sketch the graph, find its stationary points, evaluate its signed integral over this interval, and find the total area between the graph and the \(x\)-axis.',
 'hint':r'Factor \(f(x)\), then differentiate. Use the sign of the graph on each side of zero before interpreting the integral.',
 'solution':[
  r'Factor \(f(x)=x(x^2-3)\), so the roots are \(-\sqrt3,0,\sqrt3\). The derivative is \(f^{\prime}(x)=3x^2-3\), giving stationary points \((-1,2)\) and \((1,-2)\). The first is a local maximum and the second a local minimum.',
  r'The function is odd, so the signed integral over the symmetric interval is \(0\). The graph is positive on \((-\sqrt3,0)\) and negative on \((0,\sqrt3)\).',
  r'The total area is therefore \[-2\int_0^{\sqrt3}(x^3-3x)\,\mathrm{d}x=-2\left[\frac{x^4}{4}-\frac{3x^2}{2}\right]_0^{\sqrt3}=\frac92.\] The areas add even though the signed integrals cancel.'
 ],
 'extension':r'Let \(a>0\) and \(f_a(x)=x^3-3a^2x\). Predict, then calculate, the total area between this graph and the \(x\)-axis on \([-\sqrt3a,\sqrt3a]\).',
 'extension_solution':[
  r'The roots are \(-\sqrt3a,0,\sqrt3a\). Setting \(x=at\) gives \(f_a(at)=a^3(t^3-3t)\) and \(\mathrm{d}x=a\,\mathrm{d}t\). Thus widths scale by \(a\), heights by \(a^3\), and area by \(a^4\).',
  r'The total area is \(9a^4/2\). Directly, \[-2\int_0^{\sqrt3a}(x^3-3a^2x)\,\mathrm{d}x=-2\left[\frac{x^4}{4}-\frac{3a^2x^2}{2}\right]_0^{\sqrt3a}=\frac{9a^4}{2}.\] The signed integral remains zero by odd symmetry.'
 ]
}
def strings(obj):
 if isinstance(obj,str): yield obj
 elif isinstance(obj,list):
  for x in obj: yield from strings(x)
 elif isinstance(obj,dict):
  for x in obj.values(): yield from strings(x)
env=os.environ.copy()
if not env.get('NODE_PATH') and (ROOT.parent/'build-deps/node_modules/katex').exists(): env['NODE_PATH']=str(ROOT.parent/'build-deps/node_modules')
MATH=json.loads(subprocess.run(['node',str(ROOT/'scripts/render-textbook-maths.cjs')],input=json.dumps(list(set(strings([DATA,CALCULUS])))),text=True,capture_output=True,check=True,env=env).stdout)
def m(text): return MATH.get(text,e(text))
def paras(items): return ''.join('<p>'+m(x)+'</p>' for x in (items if isinstance(items,list) else [items]))
def tuition():
 return '<aside class="topic-tuition"><div><h2>Specialist tuition and guided practice</h2><p>Individual online lessons, tailored problem sheets and structured practice between lessons, focused on the areas you need to strengthen.</p></div><a class="resource-button" href="contact.html#enquiry-form">Discuss your tuition package</a></aside>'
def page(path,title,description,content):
 schema={'@context':'https://schema.org','@type':'LearningResource','name':title,'headline':title,'description':description,'url':ORIGIN+path,'datePublished':'2026-09-14','dateModified':'2026-09-14','inLanguage':'en-GB','isAccessibleForFree':True,'author':{'@type':'Person','name':'Arij Asad','url':ORIGIN+'about.html'}}
 return install_archive_navigation(f'''<!DOCTYPE html>
<html lang="en-GB"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>{e(title)} | Arij Asad</title><meta name="description" content="{e(description)}"><link rel="canonical" href="{ORIGIN+path}">
<link rel="icon" href="/favicon.ico?v=dd9f0d4a0c"><meta name="theme-color" content="#111111">
<link rel="stylesheet" href="site.css?v=challenges-20260910"><link rel="stylesheet" href="topic-practice.css?v=20260912-2"><link rel="stylesheet" href="diagnostic-practice.css?v=20260914-1">
<meta property="og:type" content="article"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{ORIGIN+path}"><meta property="og:image" content="{ORIGIN}assets/social-preview.jpg"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)}"><meta name="twitter:description" content="{e(description)}"><meta name="twitter:image" content="{ORIGIN}assets/social-preview.jpg">
<script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head>
<body class="resource-page topic-page diagnostic-page"><a class="skip-link" href="#main-content">Skip to main content</a>{HEADER}<main id="main-content">{content}</main>{FOOTER}<script src="site.js?v=20260914-1" defer></script></body></html>''',path)
def hero(kicker,title,lede,jumps):
 return f'''<header class="topic-hero"><div class="container"><nav class="topic-breadcrumbs" aria-label="Breadcrumb"><a href="resources.html">Resources</a><span>/</span><a href="maths-topic-practice.html">Topic practice</a></nav><p class="topic-kicker">{kicker}</p><h1>{title}</h1><p class="topic-lede">{lede}</p><p class="topic-byline">Original teaching resource by <a href="about.html">Arij Asad</a></p><nav class="topic-jumps" aria-label="Page sections">{jumps}</nav></div></header>'''

downloads='''<section class="diagnostic-section" id="downloads"><p class="topic-kicker">Print, teach, adapt</p><h2>Download the diagnostic pack</h2><p>Separate question and follow-up sheets leave room for working. The teacher version includes full solutions, likely errors to look for and the paired follow-up answers.</p><div class="diagnostic-downloads"><a href="assets/algebra-diagnostic/algebra-to-tmua-questions.pdf">Questions (PDF)</a><a href="assets/algebra-diagnostic/algebra-to-tmua-follow-up.pdf">Follow-up questions (PDF)</a><a href="assets/algebra-diagnostic/algebra-to-tmua-teacher-solutions.pdf">Teacher solutions (PDF)</a><a href="assets/algebra-diagnostic/algebra-to-tmua-overleaf.zip" download>Editable LaTeX for Overleaf (ZIP)</a></div><p class="diagnostic-caption">Free to use in lessons and for personal study. Please retain Arij Asad’s credit when sharing these original sheets.</p></section>'''
cards=''
for q in DATA['questions']:
 n=q['number']
 links=''.join(f'<li><a href="{e(href)}">{e(label)}</a></li>' for href,label in q['links'])
 cards+=f'''<article class="diagnostic-card" id="question-{n}"><div class="diagnostic-question"><p class="diagnostic-number">Question {n}</p><h3>{e(q['title'])}</h3>{paras(q['prompt'])}</div><div class="diagnostic-answer"><details><summary>Show a hint</summary><div>{paras(q['hint'])}</div></details><details><summary>Show the solution and review</summary><div>{paras(q['solution'])}<p><strong>Answer:</strong> {m(q['answer'])}</p><aside class="diagnostic-review"><h4>Check your reasoning</h4>{paras(q['misconception'])}</aside><h4>Matched practice</h4><ul>{links}</ul></div></details><details><summary>Try the follow-up question</summary><div>{paras(q['followup'])}<details><summary>Show the follow-up solution</summary><div>{paras(q['followup_solution'])}<p><strong>Answer:</strong> {m(q['followup_answer'])}</p></div></details></div></details></div></article>'''
route_rows=''.join(f'<tr><th scope="row"><a href="#question-{q["number"]}">{q["number"]}</a></th><td>{e(q["title"])}</td><td><a href="{e(q["links"][0][0])}">{e(q["links"][0][1])}</a></td></tr>' for q in DATA['questions'])
content=hero('Algebra · Graphs · Reasoning','Algebra to TMUA: a short diagnostic','Eight original questions to help you decide what to practise next, with hints, full explanations and a matched follow-up for every question.','<a href="#questions">Try the questions</a><a href="#review">Choose your next step</a><a href="#downloads">Download the pack</a>')
content+='''<div class="container diagnostic-content"><section class="diagnostic-section" id="how-to-use"><h2>Try first, then choose your practice</h2><p>Allow about 20 minutes for a first attempt, without a calculator. Keep your working and mark any question where you guessed or needed a hint. Take longer if it helps you explain your reasoning.</p><p>This is a short teaching diagnostic, not a TMUA mock, a complete syllabus assessment or a score predictor. Use the questions to find a useful next practice step.</p><ol><li>Attempt the questions before revealing the hints or solutions.</li><li>Find the first step where your reasoning changed direction, and explain the correction.</li><li>Work through the matched topic or textbook chapter, then try the follow-up from a clean page.</li></ol><p>Teaching a lesson? Use the <a href="teaching-practice-sequences.html#algebra-to-tmua">algebra-to-TMUA practice sequence</a> to turn the results into a focused session.</p></section>'''
content+=f'''<section class="diagnostic-section" id="questions"><h2>Eight questions to get started</h2><p>All answers stay closed until you choose to open them.</p>{cards}</section><section class="diagnostic-section" id="review"><h2>Turn an error into a next step</h2><p>A correct answer reached by guessing still deserves a review. Choose one or two areas, rather than repeating every exercise at once.</p><div class="diagnostic-table-wrap"><table class="diagnostic-routes"><thead><tr><th scope="col">Question</th><th scope="col">Skill to review</th><th scope="col">Start here</th></tr></thead><tbody>{route_rows}</tbody></table></div><p>After the follow-up feels secure, return to a mixed set from the <a href="tmua-paper-archive.html">TMUA paper archive</a> and explain how you chose each method.</p></section>{downloads}{tuition()}</div>'''
(ROOT/'algebra-to-tmua-diagnostic.html').write_text(page('algebra-to-tmua-diagnostic.html','Algebra to TMUA Diagnostic: Questions & Solutions','Eight free algebra diagnostic questions with worked solutions, follow-up practice and an editable Overleaf pack for students and teachers.',content))

content=hero('For lessons and independent practice','From textbook skills to admissions problems','Two practical sequences for choosing a starting point, repairing a gap and applying the idea in an unfamiliar problem.','<a href="#algebra-to-tmua">Algebra to TMUA</a><a href="#calculus-to-step">Calculus to STEP</a><a href="algebra-to-tmua-diagnostic.html#downloads">Download the diagnostic</a>')
content+='''<div class="container diagnostic-content"><section class="diagnostic-section"><h2>Plan around the reasoning you can see</h2><p>Ask the student to keep their working, including abandoned attempts. Choose the next task from the first uncertain step: a definition, an algebraic move, a graph or a decision about cases.</p><p>The timings below are flexible starting points for a 45-minute session. Shorten or extend each stage to fit the student.</p></section><section class="diagnostic-section" id="algebra-to-tmua"><p class="topic-kicker">Sequence 1</p><h2>Algebra to TMUA</h2><p><strong>Before the lesson:</strong> ask the student to try the <a href="algebra-to-tmua-diagnostic.html">20-minute algebra diagnostic</a>. Bring their working, not just their final answers.</p><ol class="practice-sequence"><li><h3>Review one decision <span>5 minutes</span></h3><p>Choose one uncertain answer. Ask: “What did you know at this point?” and “Which condition must still be true?” Note whether the gap is a method, a sign, a domain restriction or the meaning of “and”.</p></li><li><h3>Repair the foundation <span>10 minutes</span></h3><p>Use the question’s matched topic guide or textbook chapter. Ask the student to explain one worked example, close it, and reproduce the reasoning. Choose a few relevant exercises from their own textbook; use the linked SolutionBank only after an attempt.</p></li><li><h3>Check transfer <span>10 minutes</span></h3><p>Try the paired follow-up without the model solution. Change one condition verbally and ask what would change in the argument. A remembered answer is less useful than a reason that survives this change.</p></li><li><h3>Return to a mixed problem <span>15 minutes</span></h3><p>Choose an algebra or graph question from the <a href="tmua-paper-archive.html">TMUA archive</a> that fits the student’s current preparation. Hide its topic label. Ask the student to name the clue that suggested their method.</p></li><li><h3>Set the next practice <span>5 minutes</span></h3><p>Write one specific habit to use next time, then assign a small mixed set. At the next lesson, retry one question from a clean page before looking at the old solution.</p></li></ol><aside class="diagnostic-review"><h3>Useful prompts</h3><p>“Where might the denominator vanish?” · “Which sign are you assuming?” · “Do you need both conditions?” · “What happens at the boundary?”</p></aside><p><a class="diagnostic-inline-button" href="algebra-to-tmua-diagnostic.html#downloads">Get the question sheets and teacher solutions</a></p></section>'''
content+=f'''<section class="diagnostic-section" id="calculus-to-step"><p class="topic-kicker">Sequence 2</p><h2>Calculus and graph sketches to STEP</h2><p>For a student who already knows differentiation and basic integration, use a short problem to connect graph shape, signs and area before moving to a longer STEP question.</p><ol class="practice-sequence"><li><h3>Sketch before integrating <span>10 minutes</span></h3><p>Find the roots and stationary points in the original problem below. Ask the student to predict which parts of the graph contribute positive or negative signed area.</p></li><li><h3>Calculate and interpret <span>10 minutes</span></h3><p>Calculate the signed integral and total area separately. Have the student explain why the two answers differ, using their sketch and a sentence as well as equations.</p></li><li><h3>Generalise with a parameter <span>15 minutes</span></h3><p>Try the extension. Predict the power of the parameter in the area before integrating, then check the prediction by substitution or direct calculation.</p></li><li><h3>Explain and transfer <span>10 minutes</span></h3><p>Write a complete solution with the interval and sign choices stated. Use the <a href="strong-step-solution.html">guide to writing a strong STEP solution</a>, then choose a suitable calculus question from the <a href="step-past-papers.html">STEP archive</a> for further practice.</p></li></ol><article class="diagnostic-card"><div class="diagnostic-question"><p class="diagnostic-number">Original practice</p><h3>Signed integral or total area?</h3>{paras(CALCULUS['prompt'])}</div><div class="diagnostic-answer"><details><summary>Show a hint</summary><div>{paras(CALCULUS['hint'])}</div></details><details><summary>Show the full solution</summary><div>{paras(CALCULUS['solution'])}</div></details></div></article><article class="diagnostic-card"><div class="diagnostic-question"><p class="diagnostic-number">Extension</p><h3>Predict the effect of a parameter</h3>{paras(CALCULUS['extension'])}</div><div class="diagnostic-answer"><details><summary>Show the full solution</summary><div>{paras(CALCULUS['extension_solution'])}</div></details></div></article><aside class="diagnostic-review"><h3>Check the foundation if needed</h3><p>Revisit <a href="calculus-and-graph-sketches.html">calculus and graph sketches</a>, <a href="edexcel-pure-year-1.html#chapter-12">Pure Year 1 differentiation</a> and <a href="edexcel-pure-year-1.html#chapter-13">integration</a>. For broader integration methods, use <a href="edexcel-pure-year-2.html#chapter-11">Pure Year 2 integration</a>.</p></aside></section><section class="diagnostic-section"><h2>Keep the practice useful</h2><p>Finish with a short explanation the student can use again: what the clue was, which method it suggested and how they checked the result. Choose subsequent questions from their work rather than from a fixed score threshold.</p><p class="diagnostic-caption">The diagnostic and examples here are original resources by Arij Asad. Linked textbooks, SolutionBank materials and past papers belong to their credited publishers and creators. Use the current official specification when choosing admissions-test practice.</p></section>{tuition()}</div>'''
(ROOT/'teaching-practice-sequences.html').write_text(page('teaching-practice-sequences.html','Maths Teaching Sequences: Algebra to TMUA & Calculus to STEP','Two free lesson and independent-practice sequences connecting textbook skills, original diagnostic questions and TMUA or STEP problem solving.',content))
print('Built algebra diagnostic and teaching practice sequences')
